import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val st = StringTokenizer(br.readLine())
    val s = st.nextToken().toLong()
    val x = st.nextToken().toLong()

    // a + b = s, a ^ b = x
    // Let c = a & b, then:
    // s = x + 2*c  =>  c = (s - x) / 2
    val diff = s - x
    if (diff < 0 || diff % 2L != 0L) {
        println(0)
        return
    }
    val c = diff / 2L

    // c and x must not share any set bit: (c & x) == 0
    if ((c and x) != 0L) {
        println(0)
        return
    }

    // Count number of bits set in x; each such bit gives 2 choices
    var bits = 0
    var tempX = x
    while (tempX > 0) {
        if ((tempX and 1L) == 1L) bits++
        tempX = tempX shr 1
    }

    // Total combinations: 2^bits
    var result = 1L shl bits

    // Exclude the case where a or b is zero:
    // When c == 0, pair (0, x) and (x, 0) are counted but invalid since a,b must be positive.
    if (c == 0L) {
        result -= 2L
    }

    println(result)
}

