    val x = st.nextToken().toLong()

    // a + b = s, a ^ b = x
    // Let c = a & b, then:
    // s = x + 2*c  =>  c = (s - x) / 2, must be non-negative and integer
    val diff = s - x
    if (diff < 0 || diff % 2L != 0L) {
        println(0)
        return
    }
