    // c and x must not share any '1' bits: (c & x) == 0
    if ((c and x) != 0L) {
        println(0)
        return
    }

    // Count number of bits set in x; each such bit gives 2 choices
    var bits = 0
    var tempX = x
    while (tempX > 0) {
        if ((tempX and 1L) == 1L) bits++
        tempX = tempX shr 1
    }

    // Number of ordered pairs (a,b) with a,b >= 0 is 2^bits
    var result = 1L shl bits

    // Exclude the case where both a and b are zero (only when x == 0)
    // but we require a,b to be positive, so subtract 2 if that case exists:
    // For x == 0, solutions are (c, c) only; ordered pair count is 1.
    // We must ensure a > 0 and b > 0, so if c == 0, no solutions.
    if (x == 0L) {
        // Only (c, c) exists; result currently is 1
        // If c > 0, it's valid; if c == 0, no solutions.
        result = if (c > 0) 1L else 0L
    }

    println(result)
}

